  "tools": [
    {
      "type": "function",
      "description": "Propose ONE change to the model. This does NOT change anything: it records an exact proposal and returns its id, which you keep for authorise_change: show the user what it changes, never the id, before asking them to approve. Use the labels exactly as get_canonical_state returned them. On a host-bound drawn_link press ONLY, propose your own band, direction and one-line reason for that exact pair, shown as Olumi\u2019s estimate. For every other turn, the link is recorded with `strength` as the user\u2019s own estimate, so give ONLY the band the user named for it in this message; if they described it in their own words (\"very high\"), give your reading in `strength` and their exact phrase in `from_words`, and show it; if they named none, ask how strong the effect is first \u2014 a band they did not say is refused. The canvas calls the lowest band Slight: when the user calls a link slight, that IS `weak` \u2014 pass `weak`, and never ask whether slight means weak. When you ask the user for a band, use the canvas\u2019s words: slight, moderate, strong or very strong.",
      "name": "propose_model_change",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "from_label": {
            "type": "string"
          },
          "to_label": {
            "type": "string"
          },
          "direction": {
            "type": "string",
            "enum": [
              "positive",
              "negative"
            ]
          },
          "strength": {
            "type": "string",
            "enum": [
              "weak",
              "moderate",
              "strong",
              "very strong"
            ],
            "description": "The band the user said for this link in THIS message, in their own words \u2014 or your reading of their own words, given with `from_words`. Only for the host-bound drawn_link pair, your own Olumi estimate is allowed."
          },
          "reason": {
            "type": "string",
            "maxLength": 140,
            "description": "For a host-bound drawn link: one short plain line explaining your estimate, with no figures."
          },
          "from_words": {
            "type": "string",
            "description": "When the user described the strength in their own words rather than a band word, give their exact phrase here and your reading in `strength`; the user approves your reading. Copy it exactly from their message this turn (for example \"very high\"); never a phrase they did not write."
          },
          "rationale": {
            "type": "string",
            "description": "Why this link matters, in the user\u2019s terms."
          }
        },
        "required": [
          "from_label",
          "to_label",
          "direction",
          "strength",
          "reason",
          "from_words",
          "rationale"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Apply a previously returned proposal. Call this ONLY after the user has explicitly approved that specific proposal in their own words. The stored proposal is applied \u2014 nothing is regenerated. Report exactly what the result says, including a refusal.",
      "name": "authorise_change",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "proposal_id": {
            "type": "string"
          }
        },
        "required": [
          "proposal_id"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Withdraw an eligible, unapproved change you proposed in this turn that you now judge wrong, before you reply. You may also withdraw an earlier-turn card only when it is Olumi\u2019s own estimate, still offered on this scenario, unapproved and unapplied, and bound to the model it was made for. Do not use this to withdraw the user\u2019s own figures, edits or words, or a protected card-only removal, rename, statement or quote confirmation; an unresolved goal reading has only the exact exception below. Existing ownership, approval, freshness and model-binding checks still apply. On success the card is set aside without applying it, its buttons are removed and the existing confirmation is shown once. On refusal the card remains unchanged: explain what you doubt and the actual refusal reason when supplied, without claiming withdrawal or inventing a cause. Never ask the user not to approve a change you leave offered. An unresolved goal reading (goal-scope: ID) may also be withdrawn, but only when the user writes exactly \"Withdraw this unresolved goal reading: <goal_id>\". Otherwise retain its question.",
      "name": "withdraw_proposal",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "proposal_id": {
            "type": "string"
          }
        },
        "required": [
          "proposal_id"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Run the analysis over the persisted model. It may refuse and explain what is missing; report that honestly rather than guessing what the result would have been.",
      "name": "run_analysis",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "reason": {
            "type": "string"
          },
          "effects_timing": {
            "anyOf": [
              {
                "type": "string",
                "enum": [
                  "in_place_by_period",
                  "later_or_partial",
                  "not_stated"
                ]
              },
              {
                "type": "null"
              }
            ],
            "description": "Your reading of the current held target, its period and the options being analysed, using the current canonical model and all relevant readable user statements, including later turns. Choose in_place_by_period only when those statements support the relevant effects being fully in place by that period; later_or_partial when a relevant effect arrives later or only partly; not_stated only when the complete readable relevant source states no effects timing (the goal's period alone is not effects timing). Use null when required context is missing, truncated, unreadable, has unknown authorship, conflicts, or cannot be classified reliably; never turn unknown into not_stated. In reason, identify the actual target/period and the source or missing context for your reading. This is Olumi's interpretation, not a measurement, human approval or a change to the user's evidence."
          }
        },
        "required": [
          "reason",
          "effects_timing"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Build the model from the user\u2019s brief when get_canonical_state reports the model is empty. Preserves the user\u2019s own facts, numbers and constraint wording, then adds the options, factors, risks and causal mechanisms that make the question reasonable to analyse. Report honestly what it says was left out. With a saved model, call only for the user\u2019s explicit CURRENT request to generate a replacement model; pass that complete verified request verbatim in explicit_rebuild_request. Correction, quotation, hypothetical, negation or an earlier request is not current rebuild permission. Prepare ONE candidate through the existing construction/admission/widening pipeline, using the retained brief, verified corrections, answered context, current aim, sources and dissent; do not revive rejected mechanisms or obsolete aims. Show the complete proposed replacement, retained work, omissions and changed assumptions. Nothing replaces the saved model before this card\u2019s own approval and complete candidate save/readback. Never rebuild automatically to apply a correction.",
      "name": "build_model_from_brief",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "brief": {
            "type": "string",
            "description": "For initial construction, the user\u2019s brief verbatim. For an explicitly requested replacement, Olumi\u2019s proposed framing; it is context, never human source."
          },
          "explicit_rebuild_request": {
            "type": "string",
            "description": "Only for a saved model: the complete verified current typed request verbatim."
          },
          "explicit_draft_request": {
            "type": "string",
            "description": "Use only when the user explicitly requests a provisional draft now. Quote the complete applicable CURRENT typed request verbatim, including negation, conditions and qualifications. A request to discuss drafting, a quoted example, a conditional future request or an ambiguous yes is not that instruction. This arg does not grant approval for unrelated edits, replacing an existing saved model, or numerical analysis. Keep supplied facts and any stated aim or limits; missing information remains unknown. Any added framing, option or assumption is Olumi\u2019s provisional suggestion, never attributed to the user."
          },
          "whole_request": {
            "type": "boolean",
            "description": "true ONLY when this one call does everything the user asked for in their latest message: no other change to make, no question to answer, nothing else to explain. If there is anything more, or you are unsure, false."
          }
        },
        "required": [
          "brief",
          "explicit_rebuild_request",
          "explicit_draft_request",
          "whole_request"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Propose starting values for factors that have none, so the model can be reasoned about instead of sitting blank. This does not change anything: it records an exact proposal and returns its id for authorise_change. Show the complete approval card with every proposed value, its unit, source, basis and qualifications, and any omitted or unsupported parts; never show the id as consent. Supply the required user_stated boolean for every item: true identifies a user-supplied figure whose source must verify; false explicitly proposes a new Olumi estimate with its own basis, or identifies an existing recorded Olumi estimate when keep is true. Missing or unverifiable source is unknown, not evidence of a new AI estimate. Preserve verified human origin, known unknown source and the original words separately from a new interpretation; approval adopts an estimate without changing its original authorship. An Olumi estimate is an assumption to adopt or correct, never a measurement; a value the result marks your_figure is the user's own figure and must not be called an Olumi assumption. Propose only factors the model actually has, using the labels returned by get_canonical_state. A factor that already holds a value is left alone unless revise is true, which is allowed only when the user has just requested that factor's change and supplied the replacement figure. Never replace someone's figure with one of your own under revise. When the user requests a revision without a replacement figure, ask what figure they would use; never supply a number or an instruction for them to repeat as their own. When the user says the current recorded Olumi estimate should stay, use keep: true instead: the value does not change, and approval records acceptance of Olumi's estimate. Keep and revise retain their existing separate approval and permission checks.",
      "name": "propose_assumptions",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "assumptions": {
            "type": "array",
            "description": "The factors to give a starting value, with the reasoning for each.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "user_stated": {
                  "type": "boolean",
                  "description": "Set true ONLY for a figure the user supplied for this factor, with its actual source; the host must verify that source before recording it as theirs. A verified retained human statement counts. Set false ONLY when explicitly proposing a new Olumi estimate now, with its own basis; for keep: true, false identifies the existing recorded Olumi estimate being retained. Never infer false from missing, truncated or unmatched source, or from the absence of a user-authorship claim. Do not use false to relabel an old quoted, copied or recorded figure. Keep the original statement, subject and qualifications separate from any new interpretation. This flag is a claim to check, not proof of authorship; accepting an Olumi estimate does not turn it into a user-supplied fact."
                },
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number"
                },
                "unit": {
                  "type": "string"
                },
                "basis": {
                  "type": "string",
                  "description": "Why this is a reasonable starting point, in the user\u2019s terms."
                },
                "revise": {
                  "type": "boolean",
                  "description": "Set true ONLY when the user has just asked for this factor to be changed and gave the number. It permits replacing a value that is already there; the approval will show the user both the current value and the new one. Omit it in every other case."
                },
                "keep": {
                  "type": "boolean",
                  "description": "Set true ONLY when the user has just said Olumi\u2019s CURRENT figure for this factor is right and should stay. The stored figure is kept exactly (give it as value); it stays Olumi\u2019s estimate and the approval records that the user accepted it. Never on the user\u2019s own figure or one from their brief, never with a different number, and never in the same call as other values. Omit it in every other case."
                },
                "statements": {
                  "type": "array",
                  "minItems": 1,
                  "maxItems": 1,
                  "description": "The user\u2019s complete statement about this factor, copied exactly from their brief or a message. (a) A figure they already WROTE that the model holds as unverified (for example \"from \u00a349 to \u00a359 per month\" for today\u2019s price): form \"point\" with that figure as value, user_stated true and the same figure as value; approval records it as theirs and never changes it. (b) Words that DESCRIBE the factor without a figure (for example \"I\u2019m not that experienced with marketing\"): form \"describes\", with user_stated false, your own estimate as value and your reading as basis; the card quotes their words and the figure stays your estimate. (c) A figure they gave for this factor\u2019s level today in words that do not name the factor (for example \"about 60% of my working time goes on it\"): where the conversation makes this factor the one they most likely meant, form \"point\" with that figure as value and user_stated true; the figure stays theirs, and which factor it is about stays Olumi\u2019s unverified reading after approval, shown on the card for them to accept or correct. Ask once instead when two factors fit, or when its time, scope or denominator is unclear. (d) Words saying that work on this activity has not started (for example \"nobody has begun the website redesign\"): form \"describes\", user_stated false, value 0 and, as basis, your assumption that no time goes into it now; zero is your provisional assumption, never their figure or a measurement. Words saying only that a result is unfinished or not yet reached, a plan or need, an unknown, or that the work has started do not ground zero. Omit it otherwise.",
                  "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "quote": {
                        "type": "string"
                      },
                      "speaker": {
                        "type": "string",
                        "enum": [
                          "user",
                          "other",
                          "unknown"
                        ],
                        "description": "Identify the speaker separately for each statement from its full attribution context, not merely who sent the message. Use \"user\" for the user\u2019s own assertion, goal, requirement or instruction, including their own first-person statement in the brief. Uncertainty about its truth, numerical precision or item binding does not by itself make its speaker unknown; retain that uncertainty in the claim\u2019s source, qualifications and conditions. Use \"other\" for another speaker\u2019s claim reported by the user, with or without quotation marks, and \"unknown\" when the actual claimant cannot be established. A first-person phrase inside someone else\u2019s reported claim retains that speaker. Quoting an entire report does not transfer its embedded claim to the user. A user\u2019s instruction to correct or withdraw quoted material is their instruction; the embedded claim keeps its own speaker and stance. Adopting another speaker\u2019s claim as a model input does not change who made that claim. Preserve the source, qualifications, conditions and uncertainty. Attribution alone does not turn a hypothesis, question or proposal into an asserted current fact or an adopted operative definition. This field is Olumi\u2019s interpretation of attribution, not proof of user authorship or authority to write."
                      },
                      "form": {
                        "type": "string",
                        "enum": [
                          "point",
                          "describes"
                        ]
                      },
                      "value": {
                        "type": "number"
                      }
                    },
                    "required": [
                      "quote",
                      "speaker",
                      "form",
                      "value"
                    ]
                  }
                },
                "occurrence_range": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "low_percent": {
                      "type": "number"
                    },
                    "high_percent": {
                      "type": "number"
                    }
                  },
                  "required": [
                    "low_percent",
                    "high_percent"
                  ],
                  "description": "For an existing RISK ROOT with no held likelihood or level, propose Olumi\u2019s estimated chance, in percent, that its clearly identified event happens at least once within the current bound goal period, as low and high figures. Give it with user_stated false and a grounded basis stating the event interpretation and window, alone in the call; value and unit are not used for a risk. This is Olumi\u2019s starting assumption to review, never the user\u2019s figure or a measurement. Do not guess an ambiguous event or period. Omit it for every factor."
                }
              },
              "required": [
                "user_stated",
                "factor_label",
                "value",
                "unit",
                "basis",
                "revise",
                "keep",
                "statements",
                "occurrence_range"
              ]
            }
          }
        },
        "required": [
          "assumptions"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Add an option the user has just asked for. If its exact label already identifies a stored option marked `proposed_by: olumi`, call this tool with that label and no edits to offer adoption of the SAME option into their comparison. Its Olumi origin and suggested levels remain labelled as Olumi's; do not call it an existing user option or a user-stated figure. This does NOT change anything: it prepares ONE complete change and returns its id, which you keep for authorise_change: show the user the option and what it will be linked to, never the id, before asking them to approve. The option is linked from the decision automatically. Name the factors it would change, using the labels get_canonical_state returned. Give a level for a figure the user stated, in their own units; for an option YOU suggested you may give your own suggested figure with estimate: true and a basis, recorded and shown as Olumi\u2019s estimate. Never a placeholder. A factor with no level is added with no level, and you say plainly what is still needed. When the user asks for SEVERAL options (up to 4), put them ALL in `options` in ONE call: they become ONE change the user approves once, and it lands whole or not at all. If an option changes something the model has NO factor for, add that factor in the SAME change with `new_factors` (never link the option to an unrelated factor instead), and name it in `acts_on`. Only for something the user asked the option to change; what it changes and which way come from the user\u2019s words, or where it is plain from the option itself (a paid add-on adds revenue); if it is unclear, ask. Once a call has prepared a change, never call it again in the same reply. A call that was REFUSED prepared nothing: you may call it once more in the same reply, corrected as the refusal says.",
      "name": "propose_new_option",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "label": {
            "type": "string",
            "description": "ONE option in the user\u2019s own words. For several, use `options` instead."
          },
          "acts_on": {
            "type": "array",
            "description": "The factors this option would change, and which way. At least one.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "factor_label": {
                  "type": "string"
                },
                "direction": {
                  "type": "string",
                  "enum": [
                    "positive",
                    "negative"
                  ],
                  "description": "Whether this option pushes the factor up or down. State it; never guess it for the user."
                },
                "level": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "value": {
                      "type": "number",
                      "description": "The figure the user stated FOR THIS FACTOR, in the factor\u2019s own units (e.g. 54 for \u00a354 on a price). A figure given for something else (a price, when this factor is a churn rate) is never this factor\u2019s level: leave level out. With no figure from the user, leave level out \u2014 never 0 or any placeholder to mean \u201cnot set\u201d \u2014 unless it is your OWN suggested figure for an option you suggested: then set estimate."
                    },
                    "unit": {
                      "type": "string",
                      "description": "The unit the user stated, if any."
                    },
                    "estimate": {
                      "type": "boolean",
                      "description": "true ONLY when this figure is your own suggestion, not the user\u2019s (an option you proposed, at the figure you proposed). It is recorded and shown as Olumi\u2019s estimate, never as the user\u2019s. Needs basis."
                    },
                    "basis": {
                      "type": "string",
                      "description": "With estimate: why this figure, in plain words the user can check."
                    }
                  },
                  "required": [
                    "value",
                    "unit",
                    "estimate",
                    "basis"
                  ],
                  "description": "The level this option sets the factor to. Never give a level for a factor you add in new_factors with kind 'switch': a switch has no level of its own \u2014 the option turns it on."
                }
              },
              "required": [
                "factor_label",
                "direction",
                "level"
              ]
            }
          },
          "options": {
            "type": "array",
            "description": "Several options the user asked for (2 to 4), each with its own label and factors. One change, one approval.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "label": {
                  "type": "string",
                  "description": "The option in the user\u2019s own words."
                },
                "acts_on": {
                  "type": "array",
