      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "quantity_label": {
            "type": "string",
            "description": "Exact existing quantity label, for example Total cost."
          },
          "value": {
            "type": "number",
            "description": "The figure the user wrote, in the quantity\u2019s own units."
          },
          "rationale": {
            "type": "string"
          }
        },
        "required": [
          "quantity_label",
          "value",
          "rationale"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Change the figure of a LIMIT the model already holds (one listed under `limits` in the CURRENT MODEL STATE) when the user has just stated its new figure (for example \u201cthe budget is now \u00a330k\u201d). This does NOT change anything: it prepares ONE change and returns its id, which you keep for authorise_change: show the user the limit, its current figure and the new one, never the id, before they approve. Give the figure exactly as the user wrote it, in the limit\u2019s own unit (30000 for \u00a330k). The limit keeps its unit and meaning; only its figure changes, recorded as the user\u2019s. It never adds a limit, and never sets the goal\u2019s own target (that is propose_goal_target). A figure the user did not write is refused.",
      "name": "propose_limit_change",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "limit_label": {
            "type": "string",
            "description": "The limit\u2019s `on` label exactly as the CURRENT MODEL STATE lists it under limits."
          },
          "operator": {
            "type": "string",
            "enum": [
              "<=",
              ">="
            ],
            "description": "The limit\u2019s operator exactly as the state lists it."
          },
          "new_value": {
            "type": "number",
            "description": "The new figure the user stated, in the limit\u2019s own unit."
          },
          "stated_operator": {
            "type": "string",
            "enum": [
              "<",
              "<=",
              ">",
              ">="
            ],
            "description": "Only when the user states the comparator in this message: < for less than or under, <= for at most, > for more than, >= for at least. Omit it for a new figure alone: the limit keeps its own."
          },
          "unit": {
            "type": "string",
            "description": "The unit the user wrote the figure in, if any."
          },
          "rationale": {
            "type": "string",
            "description": "What the user said, in their words."
          },
          "whole_request": {
            "type": "boolean",
            "description": "true ONLY when this one call does everything the user asked for in their latest message: no other change to make, no question to answer, nothing else to explain. If there is anything more, or you are unsure, false."
          }
        },
        "required": [
          "limit_label",
          "operator",
          "new_value",
          "stated_operator",
          "unit",
          "rationale",
          "whole_request"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Propose the level an option sets a factor to \u2014 what the option actually DOES. An option that names a factor without saying what it sets it to blocks the comparison for EVERY option, not just itself. Give the value in the factor\u2019s own units, as the user would say it (\u00a354, not 0.27). This changes nothing: it records an exact proposal and returns its id for authorise_change; show the user what it sets first, never the id. Propose only what the user\u2019s words support; if an option\u2019s level is not stated, offer one as an assumption and say so, exactly as with propose_assumptions. A level on a factor the option is not linked to yet brings that link with it, in the same change: the link only says the option acts on that factor, so never ask how strong it is \u2014 send the level the user gave.",
      "name": "propose_option_interventions",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "interventions": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "option_label": {
                  "type": "string"
                },
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number",
                  "description": "In the factor\u2019s own units \u2014 the number a user would say."
                },
                "unit": {
                  "type": "string",
                  "description": "The unit the user wrote this figure in, if any (\u00a3 per month for \u201c\u00a310 per month\u201d)."
                },
                "basis": {
                  "type": "string"
                },
                "unmodelled_mechanisms": {
                  "type": "array",
                  "maxItems": 5,
                  "items": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 80
                  },
                  "description": "Unresolved effects this option does not yet model. Omit to preserve its existing gaps; [] explicitly requests clearing them. The user must approve the complete named gap statement, including the current gaps and questions it replaces."
                },
                "user_stated": {
                  "type": "boolean",
                  "description": "Set true ONLY for a level the user supplied for this option and factor, with its actual source; the host must verify that source before recording it as theirs. A verified retained human statement counts. Set false ONLY when explicitly proposing a new Olumi estimate now, with its own basis. Never infer false from missing, truncated or unmatched source, or from the absence of a user-authorship claim. Do not use false to relabel an old quoted, copied or recorded figure. Keep the original statement, subject and qualifications separate from any new interpretation. This flag is a claim to check, not proof of authorship; accepting an Olumi estimate does not turn it into a user-supplied fact. On an option in `status_quo_held`, a level is permitted only with true and verified user words saying that carrying on changes this factor and giving that level. Never restate the factor's starting value: carrying on as now already keeps that, so such a level is not recorded."
                },
                "likely_low": {
                  "type": "number",
                  "description": "Only with user_stated, and only when the user gave a range for this level: its low end, in the same units as value. Never a range you made up. Send it with likely_high, range_meaning and range_user_stated."
                },
                "likely_high": {
                  "type": "number",
                  "description": "The high end of that same range. Send it with likely_low."
                },
                "range_meaning": {
                  "type": "string",
                  "enum": [
                    "likely_range",
                    "min_max",
                    "at_most",
                    "at_least",
                    "other"
                  ],
                  "description": "Keep the range's actual meaning, source and qualifications. A plain likely range does not by itself specify quartiles or a probability law. likely_range uses the existing scenario carrier only for a separately grounded Olumi approximation fully disclosed on the card and adopted by its press; the user's original range remains theirs, and the approximation remains Olumi's. min_max means stated lowest/highest possible; at_most and at_least are bounds; other preserves other meanings or unresolved interpretation. If the current writer cannot represent the supplied meaning, retain that source and explain the exact limitation; do not require the user to replace retained bounds with a likely range merely to make a calculation run."
                },
                "range_user_stated": {
                  "type": "boolean",
                  "description": "Set true ONLY when the USER gave this range (both ends) for this option and factor."
                }
              },
              "required": [
                "option_label",
                "factor_label",
                "value",
                "unit",
                "basis",
                "unmodelled_mechanisms",
                "user_stated",
                "likely_low",
                "likely_high",
                "range_meaning",
                "range_user_stated"
              ]
            }
          },
          "whole_request": {
            "type": "boolean",
            "description": "true ONLY when this one call does everything the user asked for in their latest message: no other change to make, no question to answer, nothing else to explain. If there is anything more, or you are unsure, false."
          }
        },
        "required": [
          "interventions",
          "whole_request"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Propose, as ONE exact proposal the user approves ONCE, both the starting values for factors that have none AND the level each option sets \u2014 everything a first comparison needs. Use this instead of propose_assumptions + propose_option_interventions whenever both are needed: two separate proposals cannot both be applied from one approval, because applying the first changes the model the second was made against. This changes nothing on its own. Every figure you propose is an assumption for the user to adopt or correct, NEVER a measurement \u2014 say so; one the result marks `your_figure` or `stated_by: 'user'` is the user\u2019s own figure, never called an assumption. Values in the factor\u2019s own units. Give each value in the unit the saved option or factor already holds, as get_canonical_state shows it; never relabel what is counted. A level on a factor the option is not linked to yet brings that link with it, in the same change: the link only says the option acts on that factor, so never ask how strong it is \u2014 send the level the user gave.",
      "name": "propose_starting_point",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "assumptions": {
            "type": "array",
            "description": "Starting values for factors that have none. May be empty.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "user_stated": {
                  "type": "boolean",
                  "description": "Set true ONLY for a figure the user supplied for this factor, with its actual source; the host must verify that source before recording it as theirs. A verified retained human statement counts. Set false ONLY when explicitly proposing a new Olumi estimate now, with its own basis; for keep: true, false identifies the existing recorded Olumi estimate being retained. Never infer false from missing, truncated or unmatched source, or from the absence of a user-authorship claim. Do not use false to relabel an old quoted, copied or recorded figure. Keep the original statement, subject and qualifications separate from any new interpretation. This flag is a claim to check, not proof of authorship; accepting an Olumi estimate does not turn it into a user-supplied fact."
                },
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number"
                },
                "unit": {
                  "type": "string"
                },
                "basis": {
                  "type": "string"
                }
              },
              "required": [
                "user_stated",
                "factor_label",
                "value",
                "unit",
                "basis"
              ]
            }
          },
          "option_levels": {
            "type": "array",
            "description": "The level each option sets a factor to, in the factor\u2019s own units. May be empty.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "option_label": {
                  "type": "string"
                },
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number"
                },
                "basis": {
                  "type": "string"
                },
                "unmodelled_mechanisms": {
                  "type": "array",
                  "maxItems": 5,
                  "items": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 80
                  },
                  "description": "Unresolved effects this option does not yet model. Omit to preserve its existing gaps; [] explicitly requests clearing them. The user must approve the complete named gap statement, including the current gaps and questions it replaces."
                },
                "user_stated": {
                  "type": "boolean",
                  "description": "Set true ONLY for a level the user supplied for this option and factor, with its actual source; the host must verify that source before recording it as theirs. A verified retained human statement counts. Set false ONLY when explicitly proposing a new Olumi estimate now, with its own basis. Never infer false from missing, truncated or unmatched source, or from the absence of a user-authorship claim. Do not use false to relabel an old quoted, copied or recorded figure. Keep the original statement, subject and qualifications separate from any new interpretation. This flag is a claim to check, not proof of authorship; accepting an Olumi estimate does not turn it into a user-supplied fact. On an option in `status_quo_held`, a level is permitted only with true and verified user words saying that carrying on changes this factor and giving that level. Never restate the factor's starting value: carrying on as now already keeps that, so such a level is not recorded."
                }
              },
              "required": [
                "option_label",
                "factor_label",
                "value",
                "basis",
                "unmodelled_mechanisms",
                "user_stated"
              ]
            }
          }
        },
        "required": [
          "assumptions",
          "option_levels"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Retain the user\u2019s goal scope or component share, and reconcile it with the existing rate and count. Use when they correct a whole/component reading or answer its share question (including \u201c30% currently\u201d). This retains one durable question; it never writes a derived number. Supply the exact user quote and existing operand ids. If a current_level is supplied, the ordinary baseline writer prepares ONE approval for the scope, baseline and withdrawal of any incompatible product identity. Never use propose_goal_current_level alone to force a total onto a component product.",
      "name": "reconcile_goal_scope",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "goal_label": {
            "type": "string"
          },
          "scope": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "modelled": {
                "type": "string"
              },
              "alternative": {
                "type": "string"
              },
              "extent": {
                "type": "string",
                "enum": [
                  "total",
                  "component"
                ]
              },
              "stated_in_brief": {
                "type": "boolean",
                "enum": [
                  true
                ]
              },
              "source": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "quote": {
                    "type": "string"
                  }
                },
                "required": [
                  "quote"
                ]
              },
              "component": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "label": {
                    "type": "string"
                  },
                  "rate_id": {
                    "type": "string"
                  },
                  "count_id": {
                    "type": "string"
                  },
                  "share": {
                    "type": "number"
                  },
                  "basis": {
                    "type": "string",
                    "enum": [
                      "unknown",
                      "same",
                      "different"
                    ]
                  },
                  "count_basis": {
                    "type": "string"
                  },
                  "basis_source": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "quote": {
                        "type": "string"
                      }
                    },
                    "required": [
