                  },
                  "source": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "quote": {
                        "type": "string"
                      }
                    },
                    "required": [
                      "quote"
                    ]
                  }
                },
                "required": [
                  "label",
                  "rate_id",
                  "count_id",
                  "share",
                  "basis",
                  "count_basis",
                  "basis_source",
                  "source"
                ]
              }
            },
            "required": [
              "modelled",
              "alternative",
              "extent",
              "stated_in_brief",
              "source",
              "component"
            ]
          },
          "current_level": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "value": {
                "type": "number"
              },
              "unit": {
                "type": "string",
                "description": "Their native currency and the goal\u2019s stated period, e.g. GBP/month for MRR; never a normalized value."
