              "type": "object",
              "additionalProperties": false,
              "properties": {
                "option_label": {
                  "type": "string"
                },
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number",
                  "description": "In the factor\u2019s own units \u2014 the number a user would say."
                },
                "unit": {
                  "type": "string",
                  "description": "The unit the user wrote this figure in, if any (\u00a3 per month for \u201c\u00a310 per month\u201d)."
                },
                "basis": {
                  "type": "string"
                },
                "unmodelled_mechanisms": {
                  "type": "array",
                  "maxItems": 5,
                  "items": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 80
                  },
                  "description": "Unresolved effects this option does not yet model. Omit to preserve its existing gaps; [] explicitly requests clearing them. The user must approve the complete named gap statement, including the current gaps and questions it replaces."
                },
                "user_stated": {
                  "type": "boolean",
                  "description": "Set true ONLY for a level the user supplied for this option and factor, with its actual source; the host must verify that source before recording it as theirs. A verified retained human statement counts. Set false ONLY when explicitly proposing a new Olumi estimate now, with its own basis. Never infer false from missing, truncated or unmatched source, or from the absence of a user-authorship claim. Do not use false to relabel an old quoted, copied or recorded figure. Keep the original statement, subject and qualifications separate from any new interpretation. This flag is a claim to check, not proof of authorship; accepting an Olumi estimate does not turn it into a user-supplied fact. On an option in `status_quo_held`, a level is permitted only with true and verified user words saying that carrying on changes this factor and giving that level. Never restate the factor's starting value: carrying on as now already keeps that, so such a level is not recorded."
                },
                "likely_low": {
                  "type": "number",
                  "description": "Only with user_stated, and only when the user gave a range for this level: its low end, in the same units as value. Never a range you made up. Send it with likely_high, range_meaning and range_user_stated."
                },
                "likely_high": {
                  "type": "number",
                  "description": "The high end of that same range. Send it with likely_low."
                },
                "range_meaning": {
                  "type": "string",
                  "enum": [
                    "likely_range",
                    "min_max",
                    "at_most",
                    "at_least",
                    "other"
                  ],
                  "description": "Keep the range's actual meaning, source and qualifications. A plain likely range does not by itself specify quartiles or a probability law. likely_range uses the existing scenario carrier only for a separately grounded Olumi approximation fully disclosed on the card and adopted by its press; the user's original range remains theirs, and the approximation remains Olumi's. min_max means stated lowest/highest possible; at_most and at_least are bounds; other preserves other meanings or unresolved interpretation. If the current writer cannot represent the supplied meaning, retain that source and explain the exact limitation; do not require the user to replace retained bounds with a likely range merely to make a calculation run."
                },
