              "required": [
                "option_label",
                "factor_label",
                "value",
                "unit",
                "basis",
                "unmodelled_mechanisms",
                "user_stated",
                "likely_low",
                "likely_high",
                "range_meaning",
                "range_user_stated"
              ]
            }
          },
          "whole_request": {
            "type": "boolean",
            "description": "true ONLY when this one call does everything the user asked for in their latest message: no other change to make, no question to answer, nothing else to explain. If there is anything more, or you are unsure, false."
          }
        },
        "required": [
          "interventions",
          "whole_request"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Propose, as ONE exact proposal the user approves ONCE, both the starting values for factors that have none AND the level each option sets \u2014 everything a first comparison needs. Use this instead of propose_assumptions + propose_option_interventions whenever both are needed: two separate proposals cannot both be applied from one approval, because applying the first changes the model the second was made against. This changes nothing on its own. Every figure you propose is an assumption for the user to adopt or correct, NEVER a measurement \u2014 say so; one the result marks `your_figure` or `stated_by: 'user'` is the user\u2019s own figure, never called an assumption. Values in the factor\u2019s own units. Give each value in the unit the saved option or factor already holds, as get_canonical_state shows it; never relabel what is counted. A level on a factor the option is not linked to yet brings that link with it, in the same change: the link only says the option acts on that factor, so never ask how strong it is \u2014 send the level the user gave.",
      "name": "propose_starting_point",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "assumptions": {
            "type": "array",
            "description": "Starting values for factors that have none. May be empty.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "user_stated": {
                  "type": "boolean",
                  "description": "Set true ONLY for a figure the user supplied for this factor, with its actual source; the host must verify that source before recording it as theirs. A verified retained human statement counts. Set false ONLY when explicitly proposing a new Olumi estimate now, with its own basis; for keep: true, false identifies the existing recorded Olumi estimate being retained. Never infer false from missing, truncated or unmatched source, or from the absence of a user-authorship claim. Do not use false to relabel an old quoted, copied or recorded figure. Keep the original statement, subject and qualifications separate from any new interpretation. This flag is a claim to check, not proof of authorship; accepting an Olumi estimate does not turn it into a user-supplied fact."
                },
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number"
                },
                "unit": {
                  "type": "string"
                },
                "basis": {
                  "type": "string"
                }
              },
              "required": [
                "user_stated",
                "factor_label",
                "value",
                "unit",
                "basis"
              ]
            }
          },
          "option_levels": {
            "type": "array",
            "description": "The level each option sets a factor to, in the factor\u2019s own units. May be empty.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "option_label": {
                  "type": "string"
                },
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number"
                },
                "basis": {
                  "type": "string"
